const foodSpots=[[-45,38],[-41,38],[-5,38],[-1,38],[1,41],[4,41],[38,39],[42,39]];
const meetSpots=[[-3,2],[0,2],[3,2],[-3,5],[0,5],[3,5],[-3,8],[3,8]];
const npcState=[];
const residentList=document.querySelector('#residentList');
function makeBadge(){const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d');const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthTest:false}));sprite.scale.set(1.05,1.05,1);sprite.position.y=2.85;return{canvas,ctx,texture,sprite,activity:''}}
function setBadge(npc,activity){if(npc.badge.activity===activity)return;npc.badge.activity=activity;const {ctx,canvas,texture}=npc.badge;ctx.clearRect(0,0,128,128);ctx.fillStyle='#19251fe8';ctx.beginPath();ctx.arc(64,64,55,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e4bd76';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#f4e9cf';ctx.font='bold 43px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(activityInfo[activity].icon,64,64);texture.needsUpdate=true}
function renderResidents(){residentList.innerHTML=npcState.map(n=>{const a=activityInfo[n.activity]||activityInfo.home;return `<div class="resident" title="${n.name} is ${a.label}"><i>${a.icon}</i><span>${n.name}</span><small>${a.label}</small></div>`}).join('')}
function createNpc(def){const group=new THREE.Group();scene.add(group);const skin=mat(def.color),shirt=mat(def.shirt),pants=mat(0x4a4d4b),shoe=mat(0x1f2427);box(group,0,1.1,0,.6,1.05,.32,shirt);box(group,0,2.05,0,.42,.42,.38,skin);box(group,0,1.0,.16,.18,.5,.1,pants);box(group,0,1.0,-.16,.18,.5,.1,pants);box(group,0,.46,.15,.23,.2,.12,shoe);box(group,0,.46,-.15,.23,.2,.12,shoe);const badge=makeBadge();group.add(badge.sprite);const npc={...def,x:def.x,z:def.z,group,badge,target:{x:def.x,z:def.z},dir:0,phase:rand()*Math.PI*2,activity:'',anchor:{x:def.x,z:def.z}};npcState.push(npc);return npc}
for(const def of npcDefs)createNpc(def);
function npcCollides(x,z,r=.6){if(Math.abs(x)>112||Math.abs(z)>94)return true;for(const b of walls){const dx=Math.max(Math.abs(x-b.x)-b.w/2,0),dz=Math.max(Math.abs(z-b.z)-b.d/2,0);if(dx<r&&dz<r)return true}return false}
function activityAt(hour){if(hour>=22||hour<6)return'sleep';if(hour<7.5)return'eat';if(hour<8)return'commute';if(hour<12)return'work';if(hour<13)return'eat';if(hour<17)return'work';if(hour<19)return'social';if(hour<20)return'eat';return'home'}
function anchorFor(npc,activity){const i=npcState.indexOf(npc);if(activity==='sleep'||activity==='home')return{x:npc.homeX,z:npc.homeZ};if(activity==='work')return{x:npc.workX,z:npc.workZ};if(activity==='commute')return{x:npc.workX,z:npc.workZ};if(activity==='social')return{x:meetSpots[i][0],z:meetSpots[i][1]};if(activity==='eat'){if(hourOfDay()>=6&&hourOfDay()<8)return{x:npc.homeX+1.4,z:npc.homeZ};const p=foodSpots[i];return{x:p[0],z:p[1]}}return{x:npc.homeX,z:npc.homeZ}}
