function tickNpc(npc,dt){const asleep=npc.activity==='sleep';let dx=npc.target.x-npc.x,dz=npc.target.z-npc.z,dist=Math.hypot(dx,dz);if(!asleep&&dist<.65)chooseNpcTarget(npc);dx=npc.target.x-npc.x;dz=npc.target.z-npc.z;dist=Math.hypot(dx,dz);const moving=!asleep&&dist>.25;if(moving){const step=Math.min(dist,npc.speed*dt),nx=npc.x+dx/dist*step,nz=npc.z+dz/dist*step;if(!npcCollides(nx,npc.z,.62))npc.x=nx;if(!npcCollides(npc.x,nz,.62))npc.z=nz}let socialFriend=null;if(npc.activity==='social'){for(const other of npcState){if(other!==npc&&other.activity==='social'&&Math.hypot(other.x-npc.x,other.z-npc.z)<7){socialFriend=other;break}}}if(socialFriend)npc.dir=Math.atan2(socialFriend.x-npc.x,socialFriend.z-npc.z);else if(moving)npc.dir=Math.atan2(dz,dx);npc.group.rotation.y=-npc.dir+Math.PI/2;const phase=(npc.phase+=dt*(npc.activity==='eat'?6:2.5));const breathing=Math.sin(phase)*.025;const bob=moving?Math.abs(Math.sin(phase*2))*.07:breathing;if(asleep){npc.group.rotation.z=1.48;npc.group.position.set(npc.x,.3+Math.sin(phase)*.035,npc.z)}else{npc.group.rotation.z=0;npc.group.position.set(npc.x,bob,npc.z)}if(npc.activity==='eat')npc.group.rotation.x=Math.sin(phase)*.045;else npc.group.rotation.x=0}
renderResidents();

